intentos.respuesta_cruda:
{
  "sql": "SELECT COALESCE(t.product_category_name_english, 'sin_categoria') AS categoria, ROUND(SUM(CASE WHEN MAX(o.payment_installments) > 1 THEN 1 ELSE 0 END) * 100.0 / COUNT(DISTINCT o.order_id), 2) AS pct_pagos_plazos FROM order_payments o JOIN order_items oi ON o.order_id = oi.order_id LEFT JOIN product_category_translation t ON t.product_category_name = oi.product_category_name WHERE o.payment_type != 'not_defined' GROUP BY categoria HAVING COUNT(DISTINCT o.order_id) >= 100 ORDER BY pct_pagos_plazos DESC LIMIT 1"
}
